// Remove duplicates by slug
const seenSlugs = new Set<string>();
export const uniqueNames: NameEntry[] = namesDatabase.filter(n => {
  if (seenSlugs.has(n.slug)) return false;
  seenSlugs.add(n.slug);
  return true;
});

const commonMeaningFallbacks: Record<string, { meaning: string; origin: string; gender: NameEntry['gender']; pronunciation: string }> = {
  emily: { meaning: 'Rival; industrious or striving. Emily is traditionally connected with the Latin family name Aemilius.', origin: 'Latin / English', gender: 'Female', pronunciation: 'EM-uh-lee' },
  olivia: { meaning: 'Olive tree; a name associated with the olive and its long-standing symbol of peace.', origin: 'Latin / English', gender: 'Female', pronunciation: 'oh-LIV-ee-uh' },
  william: { meaning: 'Resolute protector; a traditional Germanic name formed from elements associated with will and protection.', origin: 'Germanic / English', gender: 'Male', pronunciation: 'WIL-ee-um' },
  michael: { meaning: 'Who is like God? A traditional Hebrew theophoric name.', origin: 'Hebrew', gender: 'Male', pronunciation: 'MY-kul' },
  daniel: { meaning: 'God is my judge. A traditional Hebrew name with biblical usage.', origin: 'Hebrew', gender: 'Male', pronunciation: 'DAN-yul' },
  aisha: { meaning: 'Living; alive; prosperous. A traditional Arabic feminine name.', origin: 'Arabic', gender: 'Female', pronunciation: 'EYE-sha' },
  mary: { meaning: 'A long-established biblical name with several proposed interpretations, including beloved or wished-for child.', origin: 'Hebrew / Aramaic', gender: 'Female', pronunciation: 'MAIR-ee' },
  john: { meaning: 'Yahweh is gracious. A traditional Hebrew name with extensive biblical and historical use.', origin: 'Hebrew', gender: 'Male', pronunciation: 'JON' },
  david: { meaning: 'Beloved or beloved one. A traditional Hebrew biblical name.', origin: 'Hebrew', gender: 'Male', pronunciation: 'DAY-vid' },
  noah: { meaning: 'Rest or comfort. A traditional Hebrew biblical name.', origin: 'Hebrew', gender: 'Male', pronunciation: 'NOH-uh' },
  sophie: { meaning: 'Wisdom. A French and European form related to Sophia.', origin: 'Greek / French', gender: 'Female', pronunciation: 'SOH-fee' },
  alexander: { meaning: 'Defender of the people. A Greek name formed from elements associated with defending and people.', origin: 'Greek', gender: 'Male', pronunciation: 'al-ig-ZAN-der' },
  alex: { meaning: 'Short form of Alexander or Alexandra, associated with defending or protecting people.', origin: 'Greek', gender: 'Unisex', pronunciation: 'AL-ex' },
};

function slugifyName(value: string): string {
  return value.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

/**
 * Creates a useful result for an arbitrary name that is not in the curated database.
 * This prevents dead-end searches while clearly separating generated guidance from
 * researched name entries. It must never pretend that an unknown name has a verified etymology.
 */
export function createFallbackName(rawName: string): NameEntry {
  const clean = rawName.trim().replace(/\s+/g, ' ');
  const key = clean.toLowerCase();
  const known = commonMeaningFallbacks[key];
  const first = clean.charAt(0).toUpperCase() + clean.slice(1);
  const fallbackMeaning = known?.meaning || `No single universal meaning is established for the spelling “${first}”. Name meanings can vary by language, culture, historical period, and spelling. This page provides a name insight for your search and avoids inventing an unsupported etymology.`;
  const fallbackOrigin = known?.origin || 'Varies by language and culture';
  const fallbackGender = known?.gender || 'Unisex';
  const fallbackPronunciation = known?.pronunciation || `Approximate spelling-based reading: ${first}`;
  return {
    name: first,
    slug: slugifyName(clean),
    gender: fallbackGender,
    origin: fallbackOrigin,
    meaning: fallbackMeaning,
    pronunciation: fallbackPronunciation,
    alternateNames: [],
    nicknames: [],
    relatedNames: [],
    similarNames: [],
    famousPeople: [],
    categories: ['Name Insight', 'Searchable Name'],
    popularity: { available: false },
  };
}

export function searchNames(query: string): NameEntry[] {
  if (!query.trim()) return [];
  const q = query.toLowerCase().trim();
  const matches = uniqueNames.filter(n =>
    n.name.toLowerCase().includes(q) ||
    n.origin.toLowerCase().includes(q) ||
    n.meaning.toLowerCase().includes(q) ||
    n.categories.some(c => c.toLowerCase().includes(q))
  );
  // Exact arbitrary-name fallback: every search gets a useful destination.
  if (matches.length === 0 && /^[\p{L}][\p{L} .'-]*$/u.test(query.trim())) {
    return [createFallbackName(query)];
  }
  return matches;
}

export function getNameBySlug(slug: string): NameEntry | undefined {
  const existing = uniqueNames.find(n => n.slug === slug);
  if (existing) return existing;
  const decoded = decodeURIComponent(slug).replace(/-/g, ' ').trim();
  if (!decoded) return undefined;
  return createFallbackName(decoded);
}

export function getNamesByOrigin(origin: string): NameEntry[] {
  return uniqueNames.filter(n => n.origin.toLowerCase() === origin.toLowerCase());
}

export function getNamesByGender(gender: string): NameEntry[] {
  if (gender === "Any") return uniqueNames;
  return uniqueNames.filter(n => n.gender === gender);
}

export function getNamesByCategory(category: string): NameEntry[] {
  return uniqueNames.filter(n => n.categories.some(c => c.toLowerCase() === category.toLowerCase()));
}

export function getRandomNames(count: number, filters?: { gender?: string; origin?: string; style?: string; meaning?: string }): NameEntry[] {
  let pool = [...uniqueNames];
  if (filters?.gender && filters.gender !== "Any") {
    pool = pool.filter(n => n.gender === filters.gender);
  }
  if (filters?.origin && filters.origin !== "Any") {
    const origin = filters.origin;
    pool = pool.filter(n => n.origin.toLowerCase() === origin.toLowerCase());
  }
  if (filters?.meaning) {
    const m = filters.meaning.toLowerCase();
    pool = pool.filter(n => n.meaning.toLowerCase().includes(m) || n.name.toLowerCase().includes(m));
  }
  if (filters?.style) {
    const style = filters.style.toLowerCase();
    const styleMap: Record<string, string[]> = {
      modern: ["Modern", "Popular"],
      classic: ["Classic", "Vintage"],
      unique: ["Cross-cultural"],
      short: ["Short"],
      elegant: ["Elegant", "Royal"],
      strong: ["Strong", "Historical"],
      cute: ["Nature", "Flower"],
      traditional: ["Traditional", "Religious"],
      luxury: ["Royal", "Elegant", "Noble"],
    };
    const cats = styleMap[style] || [];
    if (cats.length > 0) {
      const filtered = pool.filter(n => n.categories.some(c => cats.some(sc => c.toLowerCase().includes(sc.toLowerCase()))));
      if (filtered.length > 0) pool = filtered;
    }
  }
  // Never leave the user with a blank generator after a very specific filter.
  // First relax the style/meaning constraints, then fall back to the broad database.
  if (pool.length === 0 && (filters?.meaning || filters?.style)) {
    let broader = [...uniqueNames];
    if (filters?.gender && filters.gender !== "Any") broader = broader.filter(n => n.gender === filters.gender);
    if (filters?.origin && filters.origin !== "Any") broader = broader.filter(n => n.origin.toLowerCase() === filters.origin.toLowerCase());
    pool = broader;
  }
  if (pool.length === 0) pool = [...uniqueNames];
  const shuffled = pool.sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
}

export const allOrigins = [...new Set(uniqueNames.map(n => n.origin))].sort();
export const allCategories = [...new Set(uniqueNames.flatMap(n => n.categories))].sort();
